    ai_voice_btn = lv_btn_create(parent);
    lv_obj_set_size(ai_voice_btn, DM(46), DM(46));
    lv_obj_set_style_radius(ai_voice_btn, LV_RADIUS_CIRCLE, 0);
    lv_obj_set_style_bg_color(ai_voice_btn, lv_color_hex(COL_BLUE), 0);
    lv_obj_set_style_bg_opa(ai_voice_btn, LV_OPA_COVER, 0);
    lv_obj_set_style_shadow_width(ai_voice_btn, 10, 0);
    lv_obj_set_style_shadow_color(ai_voice_btn, lv_color_hex(COL_BLUE), 0);
    lv_obj_set_style_shadow_opa(ai_voice_btn, LV_OPA_40, 0);
    lv_obj_set_style_border_width(ai_voice_btn, 0, 0);
    lv_obj_add_flag(ai_voice_btn, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(ai_voice_btn, ai_voice_press_cb, LV_EVENT_PRESSED,
