189	    if ((int)plen >= outcap)
190	        plen = outcap - 1;
191	    size_t got = 0;
192	    while (got < plen)
193	        {
194	            int n = recv(fd, out + got, plen - got, 0);
195	            if (n <= 0)
196	                return -1;
197	            got += n;
198	        }
199	    for (size_t i = 0; i < got; i++)
200	        out[i] ^= mask[i & 3];
201	    out[got] = '\0';
202	    return (int)got;
203	}
