525	/* Build a Volcengine header (8 bytes) and wrap payload into a
526	 * standard WebSocket binary frame for sending. */
527	static int send_volc_frame(asr_tls_ctx_t* ctx,
528	    unsigned char msg_type,
529	    unsigned char serialization,
530	    const unsigned char* payload,
531	    size_t plen)
532	{
533	    unsigned char* frame = malloc(VOLC_HDR_SIZE + plen);
534	
535	    if (!frame) {
536	        return -ENOMEM;
537	    }
538	
539	    frame[0] = VOLC_PROTO_VER;
540	    frame[1] = msg_type;
541	    frame[2] = serialization;
542	    frame[3] = 0x00;
543	    frame[4] = (unsigned char)((plen >> 24) & 0xFF);
544	    frame[5] = (unsigned char)((plen >> 16) & 0xFF);
545	    frame[6] = (unsigned char)((plen >> 8) & 0xFF);
546	    frame[7] = (unsigned char)(plen & 0xFF);
547	
548	    if (plen > 0) {
549	        memcpy(frame + VOLC_HDR_SIZE, payload, plen);
550	    }
551	
552	    int ret = ws_send_binary(ctx, frame, VOLC_HDR_SIZE + plen);
553	
554	    free(frame);
555	    return ret;
556	}
